package main

import (
	"fmt"
	"os"
	"strings"
)

var reads int

func lookup(path string, id int) (string, error) {
	data, err := os.ReadFile(path)
	reads++
	if err != nil {
		return "", err
	}
	for _, line := range strings.Split(string(data), "\n") {
		var gotID int
		var name string
		if n, _ := fmt.Sscanf(line, "%d %s", &gotID, &name); n == 2 && gotID == id {
			return name, nil
		}
	}
	return "", fmt.Errorf("id %d not found", id)
}

func main() {
	var sb strings.Builder
	for i := 1; i <= 1000; i++ {
		fmt.Fprintf(&sb, "%d name%d\n", i, i)
	}
	os.WriteFile("ids.txt", []byte(sb.String()), 0o644)
	for id := 1; id <= 1000; id++ {
		lookup("ids.txt", id)
	}
	fmt.Println("file reads:", reads)
}
